/*
 * Composable for native fullscreen handling.
 *
 * Centralises the cross-browser API, tracks the current state in a
 * reactive ref and registers / cleans up the fullscreenchange
 * listeners on the target element. The native event fires for every
 * transition (button click, ESC key, browser UI), so onChange is the
 * single source of truth for side-effects.
 */
import {
  computed,
  onBeforeUnmount,
  onMounted,
  onScopeDispose,
  ref,
  shallowRef
} from 'vue'

const FULLSCREEN_EVENTS = [
  'fullscreenchange',
  'mozfullscreenchange',
  'MSFullscreenChange',
  'webkitfullscreenchange'
]

const isDocumentFullScreen = () =>
  !!(
    document.fullscreen ||
    document.webkitIsFullScreen ||
    document.mozFullScreen ||
    document.msFullscreenElement ||
    document.fullscreenElement
  )

export const getFullScreenElement = () =>
  document.fullscreenElement ||
  document.webkitFullscreenElement ||
  document.mozFullScreenElement ||
  document.msFullscreenElement ||
  null

// The unprefixed APIs return a promise that rejects when the browser
// refuses (iframe without allowfullscreen, policy, no fullscreen element):
// a denial is a no-op for the player, not an error worth reporting.
export const requestFullScreen = element => {
  if (element.requestFullscreen)
    return Promise.resolve(element.requestFullscreen()).catch(() => {})
  if (element.mozRequestFullScreen) return element.mozRequestFullScreen()
  if (element.webkitRequestFullScreen) return element.webkitRequestFullScreen()
  if (element.msRequestFullscreen) return element.msRequestFullscreen()
}

export const exitDocumentFullScreen = () => {
  if (document.exitFullscreen)
    return Promise.resolve(document.exitFullscreen()).catch(() => {})
  if (document.mozCancelFullScreen) return document.mozCancelFullScreen()
  if (document.webkitCancelFullScreen) return document.webkitCancelFullScreen()
  if (document.msExitFullscreen) return document.msExitFullscreen()
}

/**
 * @param {Object} options
 * @param {import('vue').Ref<HTMLElement>} options.container - template
 *   ref of the element to put fullscreen and to listen on
 * @param {Function} [options.onChange] - fired after fullScreen is
 *   updated; receives the new boolean
 */
export const useFullScreen = ({ container, onChange }) => {
  const fullScreen = ref(false)

  const handleNativeChange = () => {
    const nowFullScreen = isDocumentFullScreen()
    if (fullScreen.value === nowFullScreen) return
    fullScreen.value = nowFullScreen
    onChange?.(nowFullScreen)
  }

  const enter = () => container.value && requestFullScreen(container.value)
  const exit = () => exitDocumentFullScreen()

  const toggle = () => (fullScreen.value ? exit() : enter())

  onMounted(() => {
    const el = container.value
    if (!el) return
    FULLSCREEN_EVENTS.forEach(name =>
      el.addEventListener(name, handleNativeChange, false)
    )
  })

  onBeforeUnmount(() => {
    const el = container.value
    if (!el) return
    FULLSCREEN_EVENTS.forEach(name =>
      el.removeEventListener(name, handleNativeChange, false)
    )
  })

  return { fullScreen, enter, exit, toggle }
}

// One element in full screen for all the components that follow it: a list
// can hold a date field per row.
const fullScreenElement = shallowRef(null)
let followerCount = 0

const updateFullScreenElement = () => {
  fullScreenElement.value = getFullScreenElement()
}

export const useFullScreenElement = () => {
  if (followerCount === 0) {
    updateFullScreenElement()
    FULLSCREEN_EVENTS.forEach(name =>
      document.addEventListener(name, updateFullScreenElement)
    )
  }
  followerCount++
  onScopeDispose(() => {
    followerCount--
    if (followerCount === 0) {
      FULLSCREEN_EVENTS.forEach(name =>
        document.removeEventListener(name, updateFullScreenElement)
      )
    }
  })
  return fullScreenElement
}

/**
 * The element while it, or an element it holds, is in full screen, null
 * otherwise. The browser then shows nothing else: a modal opened for the
 * element must be teleported into it.
 *
 * @param {Function} getElement - returns the element, read when needed
 */
export const useFullScreenTarget = getElement => {
  const fullScreenElement = useFullScreenElement()
  return computed(() => {
    const element = getElement()
    return element?.contains(fullScreenElement.value) ? element : null
  })
}

/**
 * The element in full screen while it holds the given element, null
 * otherwise. A popup of that element teleported to <body> would open behind
 * it: it must go into the element in full screen instead.
 *
 * @param {Function} getElement - returns the element, read when needed
 */
export const useFullScreenContainer = getElement => {
  const fullScreenElement = useFullScreenElement()
  return computed(() => {
    const element = getElement()
    const container = fullScreenElement.value
    return element && container?.contains(element) ? container : null
  })
}
